// Generated by Gemini 3.6 Flash on 2026-08-19
import { CheckSquare, LogIn, LogOut, Menu, Moon, Plus, Settings as SettingsIcon, Sun, X } from "lucide-react"
import { useCallback, useEffect, useRef, useState } from "react"
import { Link, useLocation } from "wouter"
import { useTheme } from "../context/ThemeContext"
import { useClickOutside } from "../hooks/useClickOutside"
import { authApi } from "../services/api"
import { getSessionUser, signOut } from "../services/authService"
import { ProjectToggleDropdown } from "./ProjectToggleDropdown"

export const Navbar = ({ onOpenNewTaskModal, projects, enabledProjectIds, onToggleProject }) => {
	const { theme, toggleTheme } = useTheme()
	const [location, navigate] = useLocation()
	const isSettingsPage = location === "/settings"
	const [isMenuOpen, setIsMenuOpen] = useState(false)
	const [authRequired, setAuthRequired] = useState(false)
	const menuRef = useRef(null)
	// Re-read on each render so sign in/out in /register reflects here
	const sessionUser = getSessionUser()
	const [, setTick] = useState(0)
	// Logged-out visitors must not create tasks or filter projects while the
	// backend requires authentication.
	const actionsLocked = authRequired && !sessionUser

	const handleCloseMenu = useCallback(() => setIsMenuOpen(false), [])
	useClickOutside(menuRef, handleCloseMenu, isMenuOpen)

	// Close the menu whenever the route changes
	// biome-ignore lint/correctness/useExhaustiveDependencies: re-run on route change to close the menu
	useEffect(() => {
		setIsMenuOpen(false)
	}, [location])

	// Discover whether the backend requires authentication; refresh on route
	// changes so sign in/out in /register is reflected immediately.
	// biome-ignore lint/correctness/useExhaustiveDependencies: re-run on route change to refresh auth status
	useEffect(() => {
		let cancelled = false
		authApi
			.getStatus()
			.then((data) => {
				if (!cancelled) setAuthRequired(data?.auth_required === true)
			})
			.catch(() => {})
		return () => {
			cancelled = true
		}
	}, [location])

	useEffect(() => {
		if (!isMenuOpen) return
		const handleKeyDown = (event) => {
			if (event.key === "Escape") setIsMenuOpen(false)
		}
		document.addEventListener("keydown", handleKeyDown)
		return () => document.removeEventListener("keydown", handleKeyDown)
	}, [isMenuOpen])

	const handleSignOut = () => {
		signOut()
		setTick((current) => current + 1)
		setIsMenuOpen(false)
		navigate("/register")
	}

	return (
		<header className="navbar">
			<Link href="/" className="navbar-brand" title="Go to board">
				<div className="navbar-icon">
					<CheckSquare size={20} />
				</div>
				<h1 className="navbar-title">Task Tracker</h1>
			</Link>
			<div className="navbar-actions">
				{!actionsLocked && (
					<>
						<ProjectToggleDropdown projects={projects} enabledProjectIds={enabledProjectIds} onToggle={onToggleProject} />
						<button type="button" className="btn btn-primary" onClick={onOpenNewTaskModal} title="Create a new task">
							<Plus size={18} />
							<span>New Task</span>
						</button>
					</>
				)}
				<div className="navbar-menu" ref={menuRef}>
					<button
						type="button"
						className={`btn btn-icon${isMenuOpen ? " is-active" : ""}`}
						onClick={() => setIsMenuOpen((open) => !open)}
						aria-expanded={isMenuOpen}
						aria-haspopup="menu"
						title={isMenuOpen ? "Close menu" : "Open menu"}
						aria-label={isMenuOpen ? "Close menu" : "Open menu"}
					>
						{isMenuOpen ? <X size={20} aria-hidden="true" /> : <Menu size={20} aria-hidden="true" />}
					</button>
					{isMenuOpen && (
						<div className="navbar-menu-dropdown" role="menu" aria-label="Site menu">
							<Link
								href="/settings"
								role="menuitem"
								className={`navbar-menu-item${isSettingsPage ? " is-active" : ""}`}
								aria-current={isSettingsPage ? "page" : undefined}
								onClick={() => setIsMenuOpen(false)}
							>
								<SettingsIcon size={16} />
								<span>Settings</span>
							</Link>
							<button type="button" role="menuitem" className="navbar-menu-item" onClick={toggleTheme}>
								{theme === "dark" ? <Sun size={16} /> : <Moon size={16} />}
								<span>Switch to {theme === "dark" ? "Light" : "Dark"} mode</span>
							</button>
							<hr className="navbar-menu-divider" />
							{sessionUser ? (
								<>
									<p className="navbar-menu-label" title={`Signed in as ${sessionUser.username}`}>
										Signed in as {sessionUser.username}
									</p>
									<button type="button" role="menuitem" className="navbar-menu-item" onClick={handleSignOut}>
										<LogOut size={16} />
										<span>Sign out</span>
									</button>
								</>
							) : (
								<Link href="/register" role="menuitem" className="navbar-menu-item auth-highlight" onClick={() => setIsMenuOpen(false)}>
									<LogIn size={16} />
									<span>Sign in</span>
								</Link>
							)}
						</div>
					)}
				</div>
			</div>
		</header>
	)
}
